package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.eclipse.rdf4j.sail.lmdb.evaluation.NativeLmdbQuerySource.UNKNOWN_ID;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import java.nio.file.Path;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.query.QueryInterruptedException;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.NativeQuerySourceAccess;
import org.eclipse.rdf4j.sail.lmdb.RecordIterator;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The read-locked cursor wrapper holds a source read stamp until it closes, so a pending dataset close can only take
 * effect at a stride boundary or at exhaustion rather than on every pulled row.
 */
class LmdbNativeSourceCursorCheckStrideTest {

	@TempDir
	Path directory;

	@Test
	void pendingDatasetCloseIsObservedAtTheNextStrideBoundaryNotOnTheVeryNextPull() throws Exception {
		int pulled = pullsBeforeInterruption(200);
		assertTrue(pulled >= 1, "a cursor mid-stride must not re-check the open flag on every pull, pulled=" + pulled);
		assertTrue(pulled <= 200, "the pending close must interrupt the cursor at a stride boundary");
	}

	@Test
	void pendingDatasetCloseIsObservedAtExhaustionOfShortCursors() throws Exception {
		int pulled = pullsBeforeInterruption(1);
		assertTrue(pulled <= 1, "a one-row cursor must report the pending close when it is exhausted");
	}

	private static boolean isWaitingForWriteLock(Thread thread) {
		for (StackTraceElement frame : thread.getStackTrace()) {
			if ("writeLock".equals(frame.getMethodName())) {
				return true;
			}
		}
		return false;
	}

	private int pullsBeforeInterruption(int rows) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc")
				.setDirectAdjacencyEnabled(false));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			var values = repository.getValueFactory();
			IRI subject = values.createIRI("urn:example:stride:subject");
			IRI predicate = values.createIRI("urn:example:stride:predicate");
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int i = 0; i < rows; i++) {
					connection.add(subject, predicate, values.createIRI("urn:example:stride:object" + i));
				}
				connection.commit();
			}
			var dataset = NativeQuerySourceAccess.openExplicitDataset(store);
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			long subjectId = source.idOf(subject);
			long predicateId = source.idOf(predicate);
			RecordIterator cursor = source.lmdbStatements(subjectId, predicateId, UNKNOWN_ID, UNKNOWN_ID, null);
			Thread closer = new Thread(dataset::close, "stride-test-dataset-closer");
			try {
				closer.start();
				// dataset.close() flags the dataset closed, then parks on the source write lock held off by our cursor
				long deadline = System.nanoTime() + 10_000_000_000L;
				while (!isWaitingForWriteLock(closer)) {
					assertTrue(System.nanoTime() < deadline, "dataset close should wait on the cursor's read stamp");
					Thread.onSpinWait();
				}
				int pulled = 0;
				try {
					while (cursor.next() != null) {
						pulled++;
					}
				} catch (QueryInterruptedException expected) {
					return pulled;
				}
				fail("the pending dataset close must interrupt the cursor before it silently completes");
				return pulled;
			} finally {
				cursor.close();
				closer.join(10_000L);
			}
		} finally {
			repository.shutDown();
		}
	}
}
